import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

it('logs rejected field paths without values specs/hal-engine-tool-input-validation/spec.md#2', async () => {
  const warn = jest.fn();
  setLogger({debug: jest.fn(), info: jest.fn(), warn, error: jest.fn()});
  try {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async () => 'accepted'
    );
    await registry.execute('weather', {location: 123456789});
    expect(JSON.stringify(warn.mock.calls)).toMatch(/location.*string/);
    expect(JSON.stringify(warn.mock.calls)).not.toContain('123456789');
  } finally {
    setLogger();
  }
});
